<?php
// مدیریتِ چک: چکِ دریافتی از مشتری/همکار (با ثبت از بدهی کم می‌شود)، چکِ پرداختنی، سررسیدها، وصول/برگشت/عودت
$st = isset(cheque_statuses()[$_GET['tab'] ?? '']) ? $_GET['tab'] : 'pending';
echo ui_tabs(array_merge(['pending' => 'در جریان'], array_diff_key(cheque_statuses(), ['pending' => 1])), $st, 'cheques');
$bo = ui_opts("SELECT id, title name FROM bank_accounts WHERE active=1");
$in7 = (int)val("SELECT COALESCE(SUM(amount),0) FROM cheques WHERE status='pending' AND direction='in' AND due_date<=?", [date('Y-m-d', strtotime('+7 day'))]);
$out7 = (int)val("SELECT COALESCE(SUM(amount),0) FROM cheques WHERE status='pending' AND direction='out' AND due_date<=?", [date('Y-m-d', strtotime('+7 day'))]);
echo '<div class="stats">' . ui_stat('دریافتنیِ در جریان', (int)val("SELECT COALESCE(SUM(amount),0) FROM cheques WHERE status='pending' AND direction='in'")) . ui_stat('پرداختنیِ در جریان', (int)val("SELECT COALESCE(SUM(amount),0) FROM cheques WHERE status='pending' AND direction='out'"))
    . ui_stat('دریافتنی تا ۷ روزِ آینده', $in7) . ui_stat('پرداختنی تا ۷ روزِ آینده', $out7) . '</div>';
if (can('cheques.manage') || can('customers.credit')) echo '<div class="cols">' . ui_card('دریافتِ چک از مشتری/همکار', '<p class="muted">با ثبت، مبلغ از بدهیِ او کم می‌شود. اگر برگشت خورد یا عودت شد، دوباره به بدهی‌اش برمی‌گردد. سرِ سررسید به مدیران هشدار می‌رود.</p>'
    . ui_form('cheque_receive', ['customer_id' => ['مشتری/همکار', 'cpick', 1], 'number' => ['شمارهٔ چک', 'text', 1], 'sayad' => ['شناسهٔ صیادی (۱۶ رقم)', 'ltr'], 'amount' => ['مبلغ', 'money', 1], 'due' => ['سررسید', 'date', 1], 'bank' => ['بانک', 'text'], 'drawer' => ['صاحبِ حساب (صادرکننده)', 'text'], 'bank_account_id' => ['خواباندن به حسابِ', 'select', 0, $bo], 'note' => ['یادداشت', 'text']], [], ['submit' => 'ثبتِ چک']))
    . (can('bank.manage') ? ui_card('ثبتِ چکِ پرداختنی/متفرقه', ui_form('cheque_save', ['direction' => ['نوع', 'select', 1, ['out' => 'پرداختنی (چکِ ما)', 'in' => 'دریافتنی (بی‌مشتری)']], 'number' => ['شماره', 'text', 1], 'bank' => ['بانک', 'text'], 'amount' => ['مبلغ', 'money', 1], 'due' => ['سررسید', 'date', 1], 'party_name' => ['طرف', 'text'], 'bank_account_id' => ['حسابِ ما', 'select', 0, $bo]], [], ['submit' => 'ثبتِ چک'])) : '') . '</div>';
$opt = implode('', array_map(fn($k, $t) => '<option value="' . $k . '">' . h($t) . '</option>', array_keys($bo), $bo));
$rs = rows("SELECT * FROM cheques WHERE status=? ORDER BY " . ($st === 'pending' ? 'due_date' : 'status_at DESC, id DESC') . " LIMIT 500", [$st]);
echo ui_card('چک‌ها — ' . (cheque_statuses()[$st]), ui_table(['direction' => ['نوع', fn($r) => $r['direction'] === 'in' ? ui_badge('دریافتنی', 'ok') : ui_badge('پرداختنی', 'warn')], 'number' => ['شماره', 'num'], 'sayad' => ['صیادی', 'code'], 'party_name' => ['طرف', fn($r) => $r['party_type'] === 'customer' && $r['party_id'] ? '<a href="' . h(page_url('customer', ['id' => $r['party_id']])) . '">' . h($r['party_name']) . '</a>' : h((string)$r['party_name'])],
    'amount' => ['مبلغ', 'money'], 'due_date' => ['سررسید', fn($r) => jdate($r['due_date']) . ($r['status'] === 'pending' ? ($r['due_date'] < today() ? ' ' . ui_badge('گذشته', 'err') : ($r['due_date'] <= date('Y-m-d', strtotime('+' . (int)setting('cheque_remind_days', '2') . ' day')) ? ' ' . ui_badge('نزدیک', 'warn') : '')) : '')], 'bank' => 'بانک',
    'a' => ['', fn($r) => $r['status'] === 'pending' && can('cheques.manage|bank.manage') ? '<form class="filters inline" data-api="cheque_status" data-then="reload" data-confirm="وصول شد؟"><input type="hidden" name="id" value="' . $r['id'] . '"><input type="hidden" name="status" value="cleared"><select name="bank_account_id">' . str_replace('value="' . (int)$r['bank_account_id'] . '"', 'value="' . (int)$r['bank_account_id'] . '" selected', $opt) . '</select><button class="btn sm">وصول</button></form> '
        . ui_btn_api('برگشت', 'cheque_reverse', ['id' => $r['id'], 'status' => 'bounced'], ['class' => 'sm danger', 'prompt' => 'note:علتِ برگشت (اختیاری)']) . ' ' . ui_btn_api('عودت', 'cheque_reverse', ['id' => $r['id'], 'status' => 'returned'], ['class' => 'sm', 'confirm' => 'چک به صاحبش پس داده شد؟']) : '']],
    $rs, ['filter' => 1, 'empty' => 'چکی نیست.']));
